# Databricks notebook source
# MAGIC %md
# MAGIC # M68 bounded single T4 qualification
# MAGIC This is a manufactured engineering check, not scientific training.
# MAGIC Import this single file as a notebook. No other repository files are needed.
# MAGIC Leave MODE at INSPECT_ONLY until this exact release has separate execution approval.
# MAGIC The approved run uses cuda:0 only, but the whole existing cluster remains billable.
# MAGIC It does not install packages, change cluster settings or disable idle termination.
# MAGIC A failed attempt cannot be retried automatically. Never remove its intent file to retry.

# COMMAND ----------
import base64
import hashlib
import io
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import zipfile
import resource
import traceback

RELEASE_SHA256 = "6fab02865f60e344d4a48feffe3457f72380000c472c1d6ccae95174fca180a0"
RELEASE_BYTES_B64 = ""
READER_ZIP_B64 = ""
PREFIX = "followup/2026-10-19-m68-gpu-runner"
ACK = "RUN ONE BOUNDED M68 T4 QUALIFICATION"

dbutils.widgets.dropdown("MODE", "INSPECT_ONLY", ["INSPECT_ONLY", "RUN_ONCE"])
dbutils.widgets.text("ACKNOWLEDGEMENT", "")
dbutils.widgets.text("OUTPUT_ZIP", "/Volumes/development/team_eds_supplychain/b08_runtime_output/m68-t4-qualification-001.zip")

# COMMAND ----------
def run_m68_notebook():
    mode = dbutils.widgets.get("MODE")
    release_bytes = base64.b64decode(RELEASE_BYTES_B64, validate=True)
    if hashlib.sha256(release_bytes).hexdigest() != RELEASE_SHA256:
        raise ValueError("EMBEDDED_RELEASE_MISMATCH")
    release = json.loads(release_bytes)
    if mode == "INSPECT_ONLY":
        return {"decision": "INSPECTION_ONLY_GPU_RUN_NOT_AUTHORIZED",
                "release_sha256": RELEASE_SHA256,
                "required_acknowledgement": ACK,
                "planned_device": "cuda:0", "planned_maximum_run_seconds": 1800,
                "scope": "MANUFACTURED_CURRENT_LEARNER_AND_CPU_SAMPLER_ONLY",
                "torch_imported_by_notebook": False, "gpu_queried": False,
                "files_written": False, "packages_installed": False,
                "next_action": "Wait for separate approval of this release. Then set MODE=RUN_ONCE, enter the acknowledgement and Run all once."}
    if mode != "RUN_ONCE" or dbutils.widgets.get("ACKNOWLEDGEMENT") != ACK:
        raise ValueError("EXPLICIT_ONE_SHOT_APPROVAL_REQUIRED")
    started, cpu_started = time.monotonic(), time.process_time()
    child_started = resource.getrusage(resource.RUSAGE_CHILDREN)
    def totals():
        usage = resource.getrusage(resource.RUSAGE_CHILDREN)
        wrapper_cpu = time.process_time()-cpu_started
        return {"elapsed_seconds":time.monotonic()-started, "wrapper_cpu_seconds":wrapper_cpu,
                "aggregate_cpu_seconds":wrapper_cpu+usage.ru_utime+usage.ru_stime-child_started.ru_utime-child_started.ru_stime}
    output = Path(dbutils.widgets.get("OUTPUT_ZIP"))
    if (not output.is_absolute() or not str(output).startswith("/Volumes/") or output.suffix != ".zip"
            or ".." in output.parts or len(output.parts)<6):
        raise ValueError("EXISTING_UC_VOLUME_WITH_NEW_ZIP_LEAF_REQUIRED")
    if shutil.disk_usage("/tmp").free < 2*1024**3+256*1024**2:
        raise ValueError("CLUSTER_SCRATCH_RESERVE")
    archive_bytes = base64.b64decode(READER_ZIP_B64, validate=True)
    if hashlib.sha256(archive_bytes).hexdigest() != release["archive_sha256"]:
        raise ValueError("EMBEDDED_ARCHIVE_MISMATCH")
    with zipfile.ZipFile(io.BytesIO(archive_bytes)) as archive:
        if len(archive.infolist()) != len(release["members"]) or set(archive.namelist()) != set(release["members"]):
            raise ValueError("EMBEDDED_MEMBER_ROSTER")
        payloads = {}
        for name, binding in release["members"].items():
            if name.startswith("/") or ".." in Path(name).parts:
                raise ValueError("UNSAFE_ARCHIVE_PATH")
            value = archive.read(name)
            if len(value) != binding["size_bytes"] or hashlib.sha256(value).hexdigest() != binding["sha256"]:
                raise ValueError("EMBEDDED_MEMBER_BINDING")
            payloads[name] = value
    # The bounded metadata child commits this before any model/GPU child.
    # Ordinary Volume writes/readback are not a proof of power-loss durability.
    intent = (json.dumps({"release_sha256": RELEASE_SHA256, "acknowledgement": ACK,
                         "output": str(output), "started_utc_epoch": time.time(),
                         "automatic_retry": False}, sort_keys=True)+"\n").encode()
    root = Path(tempfile.mkdtemp(prefix="m68-t4-"))
    source = root/"source"
    source.mkdir()
    for name, value in payloads.items():
        path = source/name
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("xb") as stream:
            stream.write(value)
    delivery = root/"delivery"
    delivery.mkdir()
    (delivery/"release.json").write_bytes(release_bytes)
    (delivery/"reader.zip").write_bytes(archive_bytes)
    code = source/PREFIX
    # This verified stdlib module declares the exact frozen limits only.
    namespace = {}
    exec(compile(payloads[PREFIX+"/contract.py"], "<verified-m68-contract>", "exec"), namespace)
    attempt = root/"gpu-attempt-001"
    approval = {"schema":"m68-one-shot-approval-v1", "approved": True,
                "release_sha256": RELEASE_SHA256, "protocol_sha256": release["protocol_sha256"],
                "acknowledgement": ACK, "device":"cuda:0", "attempt":str(attempt),
                "limits":namespace["CUDA_LIMITS"], "existing_cluster_allowance":True,
                "automatic_retry":False, "metadata_query_authorized":True}
    (root/"approval.json").write_text(json.dumps(approval, sort_keys=True)+"\n")
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1", PYTHONHASHSEED="0")
    custody = {"__name__": "verified_m68_process_custody"}
    exec(compile(payloads[PREFIX+"/process_custody.py"], "<verified-m68-process-custody>", "exec"), custody)
    # Parent Python and cluster settings are not changed.
    command = [sys.executable,"-B",str(code/"supervisor.py"),"--project",str(source),
               "--release",str(delivery/"release.json"),"--expected-release-sha256",RELEASE_SHA256,
               "--attempt",str(attempt),"--mode","CUDA","--approval",str(root/"approval.json")]
    child, checker_code, run_error, cleanup = None, None, None, None
    def terminate(process):
        if process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=7)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait(timeout=3)
    def control_leaf(operation, value):
        remaining = 1790-totals()["elapsed_seconds"]
        if remaining < 5 or totals()["aggregate_cpu_seconds"]+3 > 1800:
            raise RuntimeError("NO_CONTROL_IO_BUDGET_LOCAL_EVIDENCE_AT:"+str(root))
        payload = root/(operation+"-payload.json")
        payload.write_bytes(value)
        with (root/(operation+".stdout")).open("xb") as out, (root/(operation+".stderr")).open("xb") as err:
            metadata = subprocess.Popen([sys.executable,"-B",str(code/"metadata_io.py"),operation,str(output),str(payload)],
                                        env=env,stdout=out,stderr=err,start_new_session=True)
            try:
                try:
                    metadata.wait(timeout=min(10,remaining))
                except subprocess.TimeoutExpired as error:
                    raise RuntimeError("CONTROL_IO_TIMEOUT_PRESERVE_NO_RETRY:"+operation+":"+str(root)) from error
            finally:
                terminate(metadata)
        if metadata.returncode != 0:
            raise RuntimeError("CONTROL_IO_FAILED_PRESERVE_NO_RETRY:"+operation+":"+str(root))
        return json.loads((root/(operation+".stdout")).read_text())
    control_leaf("intent", intent)
    try:
        with (root/"supervisor.stdout").open("xb") as out, (root/"supervisor.stderr").open("xb") as err:
            child = subprocess.Popen(command, env=env, stdout=out, stderr=err, start_new_session=True)
            try:
                child.wait(timeout=max(1,1690-totals()["elapsed_seconds"]))
            finally:
                terminate(child)
        cleanup = custody["cleanup_attempt"](attempt)
        (root/"child-cleanup.json").write_text(json.dumps(cleanup,sort_keys=True)+"\n")
        if not cleanup["all_terminated"]:
            raise RuntimeError("CHILD_TERMINATION_UNCONFIRMED_NO_RETRY")
        if child.returncode == 0:
            remaining = 1740-totals()["elapsed_seconds"]
            if remaining < 5:
                raise RuntimeError("NO_CHECKER_TIME_REMAINING")
            def checker_limits():
                resource.setrlimit(resource.RLIMIT_CPU,(30,31))
                resource.setrlimit(resource.RLIMIT_FSIZE,(8*1024**2,)*2)
            with (root/"checker.stdout").open("xb") as out, (root/"checker.stderr").open("xb") as err:
                checked = subprocess.Popen([sys.executable,"-B",str(code/"verify_saved.py"),"--attempt",str(attempt),
                                            "--output",str(attempt/"independent-check.json")],
                                           env=env, stdout=out, stderr=err, preexec_fn=checker_limits, start_new_session=True)
                try:
                    checked.wait(timeout=min(40,remaining))
                finally:
                    terminate(checked)
                checker_code = checked.returncode
    except BaseException:
        run_error = traceback.format_exc()
        if attempt.is_dir() and cleanup is None:
            try:
                cleanup = custody["cleanup_attempt"](attempt)
                (root/"child-cleanup.json").write_text(json.dumps(cleanup,sort_keys=True)+"\n")
            except BaseException:
                run_error += "\nCLEANUP_UNCONFIRMED:\n"+traceback.format_exc()
    accounting = dict(totals(), run_error=run_error, supervisor_returncode=None if child is None else child.returncode,
                      checker_returncode=checker_code, child_cleanup=cleanup,
                      local_evidence=str(root), automatic_retry=False)
    (root/"wrapper-accounting-before-export.json").write_text(json.dumps(accounting,sort_keys=True)+"\n")
    # A separately supervised stdlib child bounds potentially slow Volume I/O.
    # Failure preserves the local tree and any partial output; no repair/retry.
    remaining=1790-totals()["elapsed_seconds"]
    if remaining<5 or totals()["aggregate_cpu_seconds"]+21>1800:
        raise RuntimeError("NO_EXPORT_BUDGET_LOCAL_EVIDENCE_AT:"+str(root))
    with (root/"export.stdout").open("xb") as out,(root/"export.stderr").open("xb") as err:
        exporter=subprocess.Popen([sys.executable,"-B",str(code/"export_evidence.py"),str(root),str(output)],
                                  env=env,stdout=out,stderr=err,start_new_session=True)
        try:
            exporter.wait(timeout=min(60,remaining))
        finally:
            terminate(exporter)
    if exporter.returncode!=0:
        raise RuntimeError("EVIDENCE_EXPORT_FAILED_LOCAL_COPY_AT:"+str(root))
    exported=json.loads((root/"export.stdout").read_text())
    digest=exported["sha256"]
    checked = json.loads((attempt/"independent-check.json").read_text()) if (attempt/"independent-check.json").exists() else None
    accounting.update(totals())
    accounting.update(export_sha256=digest,export_size_bytes=exported["size_bytes"],
                      total_local_payload_bytes=sum(p.stat().st_size for p in root.rglob("*") if p.is_file()),
                      total_exported_payload_bytes=exported["size_bytes"])
    accounting["within_wrapper_limits"] = (accounting["elapsed_seconds"] <= 1800 and accounting["aggregate_cpu_seconds"] <= 1800
        and accounting["wrapper_cpu_seconds"] <= 30 and accounting["total_local_payload_bytes"]+accounting["total_exported_payload_bytes"] <= 256*1024**2)
    # Completion describes the pre-completion totals; return totals also include
    # this final bounded write/readback. Neither is a power-loss durability proof.
    accounting["measurement_scope"] = "THROUGH_EXPORT_BEFORE_COMPLETION_CONTROL_IO"
    control_leaf("completion", (json.dumps(accounting,sort_keys=True,allow_nan=False)+"\n").encode())
    accounting.update(totals())
    accounting["measurement_scope"] = "THROUGH_COMPLETION_CONTROL_IO"
    accounting["within_wrapper_limits"] = accounting["within_wrapper_limits"] and (
        accounting["elapsed_seconds"] <= 1800 and accounting["aggregate_cpu_seconds"] <= 1800
        and accounting["wrapper_cpu_seconds"] <= 30)
    ready_for_review = (accounting["within_wrapper_limits"] and not run_error
        and accounting["supervisor_returncode"] == 0 and checker_code == 0
        and checked is not None and checked.get("decision") == "PASS_SELECTED_PROFILE"
        and cleanup is not None and cleanup.get("all_terminated") is True)
    return {"decision":"RESULT_REQUIRES_REVIEW" if ready_for_review else "STOP_REVIEW_PRESERVED_EVIDENCE",
            "release_sha256":RELEASE_SHA256,
            "supervisor_returncode":accounting["supervisor_returncode"], "checker_returncode":checker_code,
            "checker":checked, "evidence_zip":str(output), "evidence_sha256":digest,
            "local_preserved_evidence":str(root), "resources":accounting,
            "automatic_retry":False, "cluster_settings_changed":False,
            "scientific_training":False, "M68_closed_by_notebook":False}

print(json.dumps(run_m68_notebook(), indent=2, sort_keys=True, allow_nan=False))
